let current=0,selected=null,parts=[],states={},history=[],step=0,help=true,tangram=0;const colors=['#d8624f','#e6aa4c','#557e58','#7971a4','#e0c849','#4b9ba5','#c37791'];
function poly(points,fill,x,y,name,angle=0){return{points,fill,x,y,name,angle}}
const rect=(w,h)=>`0,0 ${w},0 ${w},${h} 0,${h}`;
function house(){return[poly('0,0 250,0 250,125 225,125 225,25 150,25 150,125 0,125','#e6aa4c',200,175,'Thân nhà'),poly('0,75 75,0 225,0 300,75','#d8624f',175,100,'Mái nhà'),poly(rect(75,50),'#328359',225,200,'Cửa sổ'),poly('0,0 50,25 50,125 0,100','#328359',350,200,'Cánh cửa')]}
function circle(r){return Array.from({length:36},(_,i)=>`${r+r*Math.cos(i*Math.PI/18)},${r+r*Math.sin(i*Math.PI/18)}`).join(' ')}
function garden(){let a=[];for(let [x,y]of [[125,425],[200,375],[250,450]]){a.push(poly(circle(12.5),'#e8cc35',x-12.5,y-12.5,'Nhụy hoa'));for(let k=0;k<4;k++){let pts=[];for(let i=0;i<=18;i++){let t=Math.PI/2-i*Math.PI/18;pts.push(`${12.5*Math.cos(t)},${-25+12.5*Math.sin(t)}`)}a.push(poly(pts.join(' '),'#cc5749',x,y,'Cánh hoa',k*90))}}for(let[x,y]of[[550,350],[675,375],[600,450]])a.push(poly(circle(25),'#e5ce35',x-25,y-25,'Thân gà'),poly(circle(12.5),'#e5ce35',x-37.5,y-37.5,'Đầu gà'),poly('0,0 25,0 12.5,25','#635a8b',x-12.5,y-12.5,'Cánh gà'),poly('0,0 -12.5,0 0,6.25','#514843',x-37.5,y-25,'Mỏ gà'),poly('0,0 12.5,-12.5 6.25,6.25','#514843',x+25,y-12.5,'Đuôi gà'),poly('0,0 -6.25,12.5 6.25,6.25','#514843',x-6.25,y+25,'Chân gà'),poly('0,0 6.25,12.5 -6.25,6.25','#514843',x+6.25,y+25,'Chân gà'));return a}
function solids(){return[poly(rect(50,50),'#d6864b',50,25,'Mặt trước'),poly('0,0 25,-25 75,-25 50,0','#c45c55',50,25,'Mặt trên'),poly('0,0 25,-25 25,25 0,50','#655b87',100,25,'Mặt bên'),poly('0,0 50,-25 100,0 50,25','#c45c55',225,25,'Mặt trên hình khối'),poly('0,0 50,25 50,75 0,50','#d6864b',225,25,'Mặt trái hình khối'),poly('0,0 50,-25 50,25 0,50','#655b87',275,50,'Mặt phải hình khối'),poly('0,50 50,0 50,75','#be554e',50,100,'Tam giác trái'),poly('0,0 50,50 0,75','#d6864b',100,100,'Tam giác phải')]}
function tangrams(){const u=70;let a=[poly(`0,0 ${2*u},0 0,${2*u}`,colors[0],330,250,'Tam giác lớn 1',45),poly(`0,0 ${2*u},0 0,${2*u}`,colors[1],330,390,'Tam giác lớn 2',225),poly(`0,0 ${u},${u} 0,${2*u}`,colors[2],330,180,'Tam giác vừa',180),poly(rect(u,u),colors[4],330,180,'Hình vuông'),poly(`0,0 ${u},0 ${2*u},${u} ${u},${u}`,colors[5],330,180,'Hình bình hành',270),poly(`0,0 ${u},0 0,${u}`,colors[3],330,180,'Tam giác nhỏ 1',225),poly(`0,0 ${u},0 0,${u}`,colors[6],400,180,'Tam giác nhỏ 2',270)];if(tangram===1){a[0].x=370;a[0].y=260;a[0].angle=0;a[1].x=370;a[1].y=260;a[1].angle=180;a[2].x=370;a[2].y=120;a[2].angle=0;a[3].x=510;a[3].y=260;a[4].x=440;a[4].y=330;a[4].angle=0;a[5].x=370;a[5].y=400;a[5].angle=0;a[6].x=580;a[6].y=330;a[6].angle=0}if(tangram===2){a=[poly('0,0 140,0 0,140',colors[0],300,130,'Tam giác lớn 1'),poly('0,0 140,0 0,140',colors[1],440,270,'Tam giác lớn 2',180),poly('0,0 70,70 0,140',colors[2],440,130,'Tam giác vừa'),poly(rect(70,70),colors[4],370,200,'Hình vuông',45),poly('0,0 70,0 140,70 70,70',colors[5],300,270,'Hình bình hành'),poly('0,0 70,0 0,70',colors[3],300,270,'Tam giác nhỏ 1',270),poly('0,0 70,0 0,70',colors[6],440,340,'Tam giác nhỏ 2',180)]}return a}
function svgEl(tag,attrs){let e=document.createElementNS(NS,tag);for(let k in attrs)e.setAttribute(k,attrs[k]);return e}function transform(s){return`translate(${s.x} ${s.y}) rotate(${s.a}) scale(${s.f} 1)`}function targetState(p){return{x:p.x,y:p.y,a:p.angle||0,f:1,done:true}}
function deco(){return '<circle cx="600" cy="50" r="25" fill="#e3a652"/><path d="M550 75L575 50L587.5 62.5L650 25L712.5 62.5L725 50L750 75Z" fill="#6b984d"/><path d="M50 25L100 0L150 25L100 50Z M100 50L50 75L75 75Z M100 50L75 125L100 100Z" fill="#706296"/>'}
function load(n){current=n;selected=null;history=[];states={};$('#title').textContent=`${n<2?n+1:n===4?3:n===3?2:1}. ${lessons[n][1]}`;$('#instruction').textContent=lessons[n][2];$('#page').textContent=`TRANG ${lessons[n][0]} · HOẠT ĐỘNG TRONG SÁCH`;$('#lessons').innerHTML=lessons.map((l,i)=>`<button class="${i===n?'active':''}" data-lesson="${i}"><small>TRANG ${l[0]} · ${l[3]}</small><b>${l[1]}</b></button>`).join('');$('#game').hidden=n===4;$('#fold').hidden=n!==4;$('#guides').checked=true;help=true;$('#help').hidden=n===4;if(n===4){renderFold();return}parts=n===0?house():n===1?garden():n===2?solids():tangrams();$('#decor').innerHTML=n<2?deco():'';if(n===1)house().forEach(p=>$('#decor').appendChild(svgEl('polygon',{points:p.points,fill:p.fill,transform:transform(targetState(p)),stroke:'#75633c'})));$('#trayhint').innerHTML=n===3?'<label>Hình thực hành <select id="tangramChoice"><option value="0">Hình thứ nhất</option><option value="1">Hình thứ hai</option></select></label>':'Chọn một mảnh để bắt đầu.';if(n===3)$('#tangramChoice').value=tangram;render();say('Chọn một mảnh ghép rồi đặt lên bàn.');}
function render(){let tray=$('#pieces');tray.innerHTML='';$('#targets').innerHTML='';$('#placed').innerHTML='';parts.forEach((p,i)=>{let b=document.createElement('button');b.className=`piece ${selected===i?'selected':''} ${states[i]?.done?'done':''}`;b.title=p.name;b.setAttribute('aria-label',p.name);let coords=p.points.split(' ').map(v=>v.split(',').map(Number)),xs=coords.map(v=>v[0]),ys=coords.map(v=>v[1]);let minx=Math.min(...xs),miny=Math.min(...ys),w=Math.max(...xs)-minx,h=Math.max(...ys)-miny;b.innerHTML=`<svg viewBox="${minx-5} ${miny-5} ${w+10} ${h+10}"><polygon points="${p.points}" fill="${p.fill}"/></svg>`;b.onclick=()=>choose(i);tray.appendChild(b);let t=svgEl('polygon',{points:p.points,transform:transform(targetState(p)),class:'target','data-target':i});t.style.display=help?'':'none';$('#targets').appendChild(t);if(states[i]){let el=svgEl('polygon',{points:p.points,fill:p.fill,transform:transform(states[i]),class:`movable ${selected===i?'selected':''}`,'data-piece':i});$('#placed').appendChild(el)}});let count=Object.values(states).filter(s=>s.done).length;$('#progress').textContent=`${count}/${parts.length} mảnh đã ghép`;if(count===parts.length){say(current===1?'Hoàn thành! Hãy cùng chia sẻ ngôi nhà của em nhé!':'Con đã hoàn thành hình ghép!');localStorage.setItem('bai28-'+current,'done')}}
function snapshot(){history.push(JSON.stringify(states));if(history.length>80)history.shift()}function choose(i){selected=i;if(!states[i]){snapshot();states[i]={x:90,y:160,a:0,f:1,done:false}}render();say(`Đã chọn: ${parts[i].name}. Kéo mảnh hoặc chạm vị trí cần đặt.`)}function say(t){$('#message').textContent=t}
function snap(i){let s=states[i],p=parts[i],angle=((s.a-p.angle)%360+360)%360;let symmetrical=(p.name.includes('tròn')||p.name.includes('Nhụy')||p.name.includes('Thân gà')||p.name.includes('Đầu gà'));if(Math.hypot(s.x-p.x,s.y-p.y)<35&&(angle<8||angle>352||symmetrical)&&s.f===1){states[i]=targetState(p);say('Đúng vị trí rồi! Tiếp tục ghép nhé.')}else{s.done=false;say('Thử điều chỉnh vị trí hoặc xoay mảnh để khớp đường hướng dẫn.')}render()}
let drag=null;function point(e){let p=$('#board').createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform($('#board').getScreenCTM().inverse())}$('#board').addEventListener('pointerdown',e=>{let p=point(e),hit=e.target.dataset.piece;if(hit!==undefined){selected=+hit;let s=states[selected];snapshot();drag={i:selected,dx:p.x-s.x,dy:p.y-s.y};$('#board').setPointerCapture(e.pointerId);render()}else if(selected!==null){snapshot();states[selected].x=p.x;states[selected].y=p.y;snap(selected)}});$('#board').addEventListener('pointermove',e=>{if(!drag)return;let p=point(e),s=states[drag.i];s.x=Math.max(0,Math.min(800,p.x-drag.dx));s.y=Math.max(0,Math.min(520,p.y-drag.dy));s.done=false;let el=$(`#placed [data-piece="${drag.i}"]`);el.setAttribute('transform',transform(s))});function finish(){if(drag){let i=drag.i;drag=null;snap(i)}}$('#board').addEventListener('pointerup',finish);$('#board').addEventListener('pointercancel',finish);
$('#rotate').onclick=()=>{if(selected===null)return say('Hãy chọn một mảnh trước.');snapshot();states[selected].a=(states[selected].a+45)%360;snap(selected)};$('#flip').onclick=()=>{if(selected===null)return say('Hãy chọn một mảnh trước.');snapshot();states[selected].f*=-1;snap(selected)};$('#undo').onclick=()=>{if(history.length){states=JSON.parse(history.pop());if(!states[selected])selected=null;render();say('Đã hoàn tác thao tác vừa rồi.')}};$('#reset').onclick=()=>{snapshot();states={};selected=null;render();say('Bàn thực hành đã sẵn sàng.');};$('#guides').onchange=e=>{help=e.target.checked;render()};$('#help').onclick=()=>{help=true;$('#guides').checked=true;let i=selected??parts.findIndex((p,i)=>!states[i]?.done);if(i<0)return;choose(i);say(`Gợi ý: ${parts[i].name} đặt tại đường viền đang nhấp nháy. Xoay theo mẫu.`);let el=$(`#targets [data-target="${i}"]`);if(el)el.animate([{opacity:1},{opacity:.1},{opacity:1}],{duration:850,iterations:4});else{say('Dùng đủ 7 mảnh, xoay và lật để phủ kín hình mẫu, không chồng lên nhau.');$('#targets polygon')?.animate([{opacity:1},{opacity:.25},{opacity:1}],{duration:850,iterations:4})}};$('#lessons').onclick=e=>{let b=e.target.closest('[data-lesson]');if(b)load(+b.dataset.lesson)};document.addEventListener('change',e=>{if(e.target.id==='tangramChoice'){tangram=+e.target.value;load(3)}});
$('#save').onclick=()=>{let copy=$('#board').cloneNode(true);copy.setAttribute('xmlns',NS);copy.querySelector('#targets').remove();copy.querySelector('rect').setAttribute('fill','#fafaf0');copy.querySelectorAll('.movable').forEach(p=>{p.setAttribute('stroke','#42543d');p.setAttribute('stroke-width','1')});let url=URL.createObjectURL(new Blob([new XMLSerializer().serializeToString(copy)],{type:'image/svg+xml'}));let img=new Image();img.onload=()=>{let canvas=document.createElement('canvas');canvas.width=1600;canvas.height=1040;canvas.getContext('2d').drawImage(img,0,0,1600,1040);let a=document.createElement('a');a.download=`bai-28-trang-${lessons[current][0]}.png`;a.href=canvas.toDataURL();a.click();URL.revokeObjectURL(url)};img.src=url};
const steps=['Chuẩn bị một tờ giấy hình chữ nhật. Gấp tờ giấy làm đôi.','Gấp tạo thành hình tam giác.','Gấp mép giấy lên trên.','Gấp góc tờ giấy vào trong.','Tạo thành hình vuông.','Gấp thành hình tam giác.','Tạo thành hình vuông.','Tạo thành hình thuyền buồm.'];
const folds=['<path d="M105 80H295V330H105Z" fill="#dda4b7"/><path d="M200 80V330M105 205H295" class="crease"/><path d="M340 180H530V305H340Z" fill="#9c8bb9"/><path d="M435 180V305" class="crease"/>','<path d="M110 290L250 100L390 290Z" fill="#a99bc2"/><path d="M110 290H390V330H110Z" fill="#a99bc2"/><path d="M250 100V330" class="crease"/>','<path d="M110 290L250 100L390 290Z" fill="#a99bc2"/><path d="M110 250H390V290H110Z" fill="#dda4b7"/><path d="M250 100V250" class="crease"/>','<path d="M100 300L250 100L400 300Z" fill="#a99bc2"/><path d="M150 240H350V300H150Z" fill="#dda4b7"/><path d="M100 300L150 240M350 240L400 300" class="crease"/>','<path d="M250 70L390 210L250 350L110 210Z" fill="#dda4b7"/><path d="M250 70L320 210L250 290L180 210Z" fill="#a99bc2"/><path d="M250 70V350" class="crease"/>','<path d="M110 290L250 130L390 290Z" fill="#dda4b7"/><path d="M250 130V290" class="crease"/>','<path d="M250 70L370 210L250 350L130 210Z" fill="#dda4b7"/><path d="M250 70L265 210L250 350Z" fill="#a99bc2"/><path d="M250 70V350" class="crease"/>','<path d="M80 190L190 310H370L480 190L290 250Z" fill="#dda4b7"/><path d="M190 310L280 160L370 310Z" fill="#a99bc2"/><path d="M80 190L280 270L480 190M280 160V270" class="crease"/>'];
function renderFold(){ $('#fold').innerHTML=`<div class="fold-layout"><div><div class="fold-picture"><svg viewBox="0 0 600 420" stroke="#65586f" stroke-width="3" stroke-linejoin="round"><style>.crease{fill:none;stroke-dasharray:8 7;stroke-width:2}</style>${folds[step]}<text x="30" y="390" stroke="none" fill="#86768e" font-size="16">Bước ${step+1} / 8</text></svg></div><div class="fold-nav"><button id="prevStep" ${step===0?'disabled':''}>← Bước trước</button><button id="nextStep">${step===7?'✓ Đã gấp xong':'Đã làm xong · Tiếp →'}</button></div></div><div><div class="steps">${steps.map((s,i)=>`<button data-step="${i}" class="${step===i?'active':''}"><b>Bước ${i+1}.</b> ${s}</button>`).join('')}</div><p class="fold-note">✋ Chuẩn bị giấy thật để thực hành. Quan sát hoạt ảnh, tạm dừng khi cần và thực hiện từng bước với giấy thật.</p></div></div>`;$('#progress').textContent=`Bước ${step+1}/8`;say(steps[step]);$('#prevStep').onclick=()=>{step=Math.max(0,step-1);renderFold()};$('#nextStep').onclick=()=>{if(step<7){step++;renderFold()}else{say('Con đã hoàn thành thuyền buồm! Hãy chia sẻ sản phẩm với lớp.');localStorage.setItem('bai28-4','done')}};document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{step=+b.dataset.step;renderFold()})}
