const silhouettes=[[[0,400],[15,270],[95,180],[95,90],[35,25],[105,-55],[95,90],[150,-10],[230,-35],[170,70],[95,90],[175,95],[170,180],[95,180],[145,245],[145,350],[95,280],[95,350],[135,400]],[[0,90],[80,10],[160,90],[125,90],[115,110],[160,160],[225,230],[280,230],[280,315],[360,400],[360,480],[205,330],[155,390],[80,320],[130,270],[0,265],[80,185],[40,145],[20,90]],[[0,3],[2,1],[1,0],[5,0],[5,4],[4,3],[2,5]]];
let silhouette=[];
function signedArea(p){return Math.abs(p.reduce((v,a,i)=>{let b=p[(i+1)%p.length];return v+a[0]*b[1]-b[0]*a[1]},0)/2)}
function inside(x,y,p){let c=false;for(let i=0,j=p.length-1;i<p.length;j=i++){let a=p[i],b=p[j];if((a[1]>y)!=(b[1]>y)&&x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0])c=!c}return c}
function world(p,s){let r=s.a*Math.PI/180;return p.points.split(' ').map(v=>{let[x,y]=v.split(',').map(Number);x*=s.f;return[s.x+x*Math.cos(r)-y*Math.sin(r),s.y+x*Math.sin(r)+y*Math.cos(r)]})}
const baseLoad=load,baseRender=render,baseSnap=snap;
load=function(n){baseLoad(n);if(n===3){let raw=silhouettes[tangram]||silhouettes[0],scale=Math.sqrt(39200/signedArea(raw)),minX=Math.min(...raw.map(p=>p[0])),minY=Math.min(...raw.map(p=>p[1]));let maxX=Math.max(...raw.map(p=>p[0])),maxY=Math.max(...raw.map(p=>p[1])),offsetX=(800-(maxX-minX)*scale)/2,offsetY=(520-(maxY-minY)*scale)/2;silhouette=raw.map(([x,y])=>[(x-minX)*scale+offsetX,(y-minY)*scale+offsetY]);let a=70;parts=[poly(`0,0 ${a*2},0 0,${a*2}`,colors[0],0,0,'Tam giác lớn 1'),poly(`0,0 ${a*2},0 0,${a*2}`,colors[1],0,0,'Tam giác lớn 2'),poly(`0,0 ${a},${a} 0,${a*2}`,colors[2],0,0,'Tam giác vừa'),poly(rect(a,a),colors[4],0,0,'Hình vuông'),poly(`0,0 ${a},0 ${a*2},${a} ${a},${a}`,colors[5],0,0,'Hình bình hành'),poly(`0,0 ${a},0 0,${a}`,colors[3],0,0,'Tam giác nhỏ 1'),poly(`0,0 ${a},0 0,${a}`,colors[6],0,0,'Tam giác nhỏ 2')];$('#trayhint').innerHTML='<label>Hình mẫu <select id="tangramChoice"><option value="0">Hình thứ nhất</option><option value="1">Hình thứ hai</option></select></label>';$('#tangramChoice').value=tangram;render();say('Dùng đủ 7 mảnh để phủ hình mẫu. Quan sát hình mẫu để đối chiếu.')}};
render=function(){baseRender();if(current!==3)return;$('#targets').innerHTML='';$('#targets').appendChild(svgEl('polygon',{points:silhouette.map(p=>p.join(',')).join(' '),fill:'#a8bd86',opacity:'.5'}));$('#progress').textContent=`${Object.keys(states).length}/7 mảnh trên bàn`;if(!$('#checkTangram')){let b=document.createElement('button');b.id='checkTangram';b.textContent='✓ Kiểm tra';b.onclick=checkTangram;$('.toolbar').appendChild(b)}};
snap=function(i){if(current!==3)return baseSnap(i);states[i].done=false;states[i].x=Math.round(states[i].x/5)*5;states[i].y=Math.round(states[i].y/5)*5;render();say('Đã đặt mảnh. Xoay, lật và điều chỉnh để phủ kín mẫu.');};
function checkTangram(){if(Object.keys(states).length<7)return say('Hãy dùng đủ 7 mảnh ghép nhé.');let polys=parts.map((p,i)=>world(p,states[i])),target=0,hit=0,spill=0,overlap=0;for(let x=0;x<800;x+=5)for(let y=0;y<520;y+=5){let t=inside(x,y,silhouette),count=polys.filter(p=>inside(x,y,p)).length;if(t){target++;if(count)hit++}else if(count)spill++;if(count>1)overlap++}if(hit/target>.94&&spill/target<.06&&overlap/target<.04){say('Con đã ghép kín hình bằng đủ 7 mảnh. Hoàn thành!');localStorage.setItem('bai28-3','done')}else say('Chưa kín mẫu: hãy kiểm tra phần còn trống, mảnh chồng nhau và mảnh nằm ngoài hình.');}
const oldLoad=load;load=function(n){$('#checkTangram')?.remove();oldLoad(n)};
